import { useQuery } from '@tanstack/react-query';
import { useReadScope } from '../../query/live';
import type { Grade } from '../people/people';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-MM-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end). Its level is the sheet it is
 *  kept on: 0 this sheet's own, 1 its parent's, 2 its parent's parent, up to {@link RATE_LEVELS}; a cloned sheet then
 *  has the rates of the sheet it was cloned from (and so on), each RATE_LEVELS + 1 further up. Its version counts
 *  the values set for its grade and from-date, this one (the newest, the one in force) included. A forward-only rate
 *  (saved with a from-date on or after the sheet's today) carries the claim sequence's value when it was saved (after;
 *  null for a rate that applies to every claim) and the version it replaced (before; null when none): a claim added
 *  before it uses that one instead (see {@link claimRateOf}). */
export type Rate = {
  grade: Grade;
  pct: string;
  from: string | null;
  to: string | null;
  level: number;
  version: number;
  after?: number | null;
  before?: Rate | null;
};

/** The most levels up a sheet's parents give it rates. */
export const RATE_LEVELS = 3;

export const ratesKey = (sheet: string) => ['rates', sheet] as const;

export const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

/** What a candidate rate for a grade would do: how many OPEN and PENDING claims would show a different due, and the
 *  sum of the differences (new due minus current due, two decimals; negative when lower). */
export type RatePreview = { count: number; diff: string };

export const ratePreviewPath = (sheet: string, grade: Grade, pct: string) =>
  `${ratesPath(sheet)}/preview?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`;

/** Every rate on the sheet, its own by grade then from-date (the one with none first), then its parents' by level,
 *  then those of the sheet it was cloned from; a grade with no rate is absent. */
export function useRates(sheet: string) {
  const read = useReadScope(ratesKey(sheet));
  return useQuery({
    queryKey: read.key,
    queryFn: () => read.get<Rate[]>(ratesPath(sheet)),
  });
}

/** The rate for a grade on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it, or
 *  undefined when the date is before every rate the grade has, or after the to-date of that one (or the date
 *  is not yet known). When the sheet's own rates give none, the next level up is used (its parents', then
 *  those of the sheet it was cloned from). */
export function rateOf(rates: Rate[], grade: Grade | undefined, date: string | undefined): string | undefined {
  if (date === undefined || grade === undefined) return undefined;
  const top = rates.reduce((m, r) => Math.max(m, r.level ?? 0), 0);
  for (let level = 0; level <= top; level++) {
    const pct = rateAt(rates, grade, date, level);
    if (pct !== undefined) return pct;
  }
  return undefined;
}

/** The rates as a claim added at the sequence value sees them (null for one kept from before it was recorded): each
 *  forward-only rate saved after it gives way to the version it replaced, or is left out when it replaced none. */
export function seenBy(rates: Rate[], added: number | null | undefined): Rate[] {
  const seen: Rate[] = [];
  for (const rate of rates) {
    let r: Rate | null | undefined = rate;
    while (r != null && r.after != null && (added == null || added <= r.after)) r = r.before;
    if (r != null) seen.push(r);
  }
  return seen;
}

/** The rate for a grade on a claim's date, of the rates the claim sees (see {@link seenBy}). */
export function claimRateOf(rates: Rate[], grade: Grade | undefined, claim: { date: string; added?: number | null }): string | undefined {
  return rateOf(seenBy(rates, claim.added), grade, claim.date);
}

function rateAt(rates: Rate[], grade: Grade, date: string, level: number): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.level ?? 0) !== level || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < date) return undefined;
  return found?.pct;
}

/** A two-decimal string as a whole number of hundredths. */
export function hundredths(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = value.replace(/^-/, '').split('.');
  const cents = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  return negative ? -cents : cents;
}

/** A whole number of hundredths as a two-decimal string. */
export function twoDecimals(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/** An amount times a percent, divided by 100, in hundredths rounded half to even (1.025 -> 1.02,
 *  1.035 -> 1.04), or half up when `halfUp` (1.025 -> 1.03); undefined when there is no rate. Worked in whole
 *  numbers so no float error shows. */
export function dueCents(amount: string, pct: string | undefined, halfUp = false): bigint | undefined {
  if (pct === undefined) return undefined;
  const product = hundredths(amount) * hundredths(pct);
  // Rounded on the magnitude, so a negative amount (a correction) rounds as its positive would.
  const abs = product < 0n ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
  return product < 0n ? -quotient : quotient;
}

/** A due as the screen shows it: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | undefined): string {
  return cents === undefined ? 'n/a' : twoDecimals(cents);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { useGradeCodes } from '../grades/grades';
import { useSheetToday } from '../sheet/sheet';
import type { Grade } from '../people/people';
import { rateOf, ratePreviewPath, ratesKey, ratesPath, useRates } from './rates';
import type { Rate, RatePreview } from './rates';
import { Fig } from '../locale/Fig';

type Draft = { grade: Grade; pct: string; from: string; to: string };
const EMPTY: Draft = { grade: 'A', pct: '', from: '', to: '' };

// The sheet's rates: each grade's rate in force on the sheet's today (n/a when none), a calendar of each grade's rate
// on the first day of each month of today's calendar year (n/a when none), every rate with its
// from-date (a blank from-date applies from the start) and to-date (a blank one has no end), and a form that sets one, replacing the rate already
// there for that grade and from-date as a new version (each row shows its version count; the newest is in force).
function Rates({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: rates = [] } = useRates(sheet);
  const gradeCodes = useGradeCodes(sheet);
  const today = useSheetToday(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  // The rate calendar: each month (yyyy-MM) of the sheet's today's calendar year, read on its first day.
  const year = today?.slice(0, 4);
  const months = year ? Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`) : [];

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Rate[]>(byUser(ratesPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(ratesKey(sheet), updated);
      setDraft((d) => ({ ...d, pct: '', from: '', to: '' }));
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a percent that is not 0.00 or more with up to two decimals, a bad from- or to-date, or a to-date before the from-date.
    send(draft);
  };

  // The preview of a candidate rate: read-only, it saves nothing and audits nothing.
  const [previewGrade, setPreviewGrade] = useState<Grade>('A');
  const [previewPct, setPreviewPct] = useState('');
  const preview = useMutation({
    mutationFn: ({ grade, pct }: { grade: Grade; pct: string }) =>
      getJson<RatePreview>(ratePreviewPath(sheet, grade, pct)),
  });
  const runPreview = () => {
    preview.reset();
    preview.mutate({ grade: previewGrade, pct: previewPct });
  };

  return (
    <section>
      <h2>Rates</h2>
      <form onSubmit={submit}>
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {gradeCodes.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input data-testid="rate-form-pct" value={draft.pct} onChange={(e) => change({ pct: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="rate-form-from"
            placeholder="yyyy-mm-dd (blank: from the start)"
            value={draft.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="rate-form-to"
            placeholder="yyyy-mm-dd (blank: no end)"
            value={draft.to}
            onChange={(e) => change({ to: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <span data-testid="rate-form-error" role="alert">
            {' '}A rate needs one of the sheet's grades and a percent of 0.00 or more with up to two decimals, a from-date and a to-date that are each a valid date or blank, and a to-date not before the from-date.
          </span>
        )}
      </form>
      <div>
        <label>
          Preview grade{' '}
          <select
            data-testid="rate-preview-grade"
            value={previewGrade}
            onChange={(e) => {
              setPreviewGrade(e.target.value as Grade);
              preview.reset();
            }}
          >
            {gradeCodes.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Candidate rate %{' '}
          <input
            data-testid="rate-preview-pct"
            value={previewPct}
            onChange={(e) => {
              setPreviewPct(e.target.value);
              preview.reset();
            }}
          />
        </label>{' '}
        <button type="button" data-testid="rate-preview" disabled={preview.isPending} onClick={runPreview}>
          Preview
        </button>
        {preview.data && (
          <span>
            {' '}Claims changed: <span data-testid="rate-preview-count">{preview.data.count}</span>, difference:{' '}
            <span data-testid="rate-preview-diff"><Fig>{preview.data.diff}</Fig></span>
          </span>
        )}
        {preview.isError && (
          <span data-testid="rate-preview-error" role="alert">
            {' '}A preview needs one of the sheet's grades and a percent of 0.00 or more with up to two decimals.
          </span>
        )}
      </div>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {gradeCodes.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}><Fig>{rateOf(rates, g, today) ?? 'n/a'}</Fig></td>
            </tr>
          ))}
        </tbody>
      </table>
      {months.length > 0 && (
        <table>
          <thead>
            <tr>
              <th>Grade</th>
              {months.map((m) => (
                <th key={m}>{m}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {gradeCodes.map((g) => (
              <tr key={g}>
                <td>{g}</td>
                {months.map((m) => (
                  <td key={m} data-testid={`rate-month-${g}-${m}`}><Fig>{rateOf(rates, g, `${m}-01`) ?? 'n/a'}</Fig></td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>To</th>
            <th>Rate %</th>
            <th>Versions</th>
          </tr>
        </thead>
        <tbody>
          {rates.filter((r) => (r.level ?? 0) === 0).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
              <td>
                <span data-testid="rate-pct"><Fig>{r.pct}</Fig></span>
              </td>
              <td data-testid="rate-version">{r.version ?? 1}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 5, Component: Rates });
