-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet VARCHAR(200)  NOT NULL,
    grade VARCHAR(1)    NOT NULL,
    pct   DECIMAL(9, 2) NOT NULL,
    PRIMARY KEY (sheet, grade)
);
-- A rate may carry a from-date: a grade may have several rates, one per from-date, and a claim uses the one
-- whose from-date is the latest on or before its date. A null from-date applies from the beginning of time.
-- from_key is the from-date as compared, so there is one rate per sheet, grade and from-date (null included).
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet, grade, from_key);
-- A rate is kept as versions: setting a rate for a grade and from-date already there keeps the value it replaces
-- as an older version (rate_version) and makes the new one the rate in force, its version one more. The rate row
-- is always the newest version; version counts them all (the newest included).
ALTER TABLE rate ADD COLUMN version INT DEFAULT 1 NOT NULL;
CREATE TABLE rate_version (
    sheet     VARCHAR(200)  NOT NULL,
    grade     VARCHAR(1)    NOT NULL,
    from_date DATE,
    version   INT           NOT NULL,
    pct       DECIMAL(9, 2) NOT NULL,
    to_date   DATE
);
CREATE INDEX rate_version_sheet ON rate_version (sheet, grade, from_date);
-- A claim carries when it was added (claim.added, from claim_added_seq, rising as claims are added by any path; a
-- copy of a claim keeps it). A rate saved with a from-date on or after the sheet's today is forward-only: forward_after
-- is the sequence's value when it was saved, and it applies only to claims added after (added greater than it); a
-- claim added before uses the version it replaced (none when it replaced none). A null forward_after applies to every
-- claim. Older versions keep theirs in rate_version.
CREATE SEQUENCE claim_added_seq;
ALTER TABLE claim ADD COLUMN added BIGINT DEFAULT NEXT VALUE FOR claim_added_seq;
ALTER TABLE rate ADD COLUMN forward_after BIGINT;
ALTER TABLE rate_version ADD COLUMN forward_after BIGINT;
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
